1	import React, {useRef, useState} from 'react';
2	import {ColorPicker} from '@tryghost/shade/patterns';
3	import {Popover, PopoverContent, PopoverTrigger} from '@tryghost/shade/components';
4	
5	export interface ColorPickerFieldSwatch {
6	    title: string;
7	    value: string | null;
8	    hex: string;
9	}
10	
11	interface ColorPickerFieldProps {
12	    title: string;
13	    value: string | null;
14	    onChange: (color: string | null) => void;
15	    accentColor?: string;
16	    swatches?: ColorPickerFieldSwatch[];
17	}
18	
19	const VALID_HEX = /^#(?:[0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
20	
21	const normalizeColorValue = (value: string | null, accentColor?: string, swatches: ColorPickerFieldSwatch[] = []): string => {
22	    if (value && VALID_HEX.test(value)) {
23	        return value;
24	    }
25	
26	    switch (value) {
27	    case 'accent':
28	        return accentColor && VALID_HEX.test(accentColor) ? accentColor : '#ffffff';
29	    case 'light':
30	        return '#ffffff';
31	    case 'transparent':
32	        return '#00000000';
33	    default:
34	        break;
35	    }
36	
37	    const selectedSwatch = swatches.find(swatch => swatch.value === value);
38	    if (selectedSwatch) {
39	        return selectedSwatch.hex;
40	    }
41	
42	    return '#ffffff';
43	};
44	
45	const isTransparent = (hex: string) => {
46	    const normalized = hex.toLowerCase();
47	
48	    return (normalized.length === 5 && normalized[4] === '0') || (normalized.length === 9 && normalized.slice(7) === '00');
49	};
50	
51	const TransparentIndicator = () => (
52	    <span className="pointer-events-none absolute inset-0 overflow-hidden rounded-full" data-testid="transparent-indicator" aria-hidden>
53	        <span className="absolute top-1/2 left-[-30%] block h-px w-[160%] -translate-y-1/2 -rotate-45 bg-red" />
54	    </span>
55	);
56	
57	const ColorPickerField: React.FC<ColorPickerFieldProps> = ({title, value, onChange, accentColor, swatches = []}) => {
58	    const [open, setOpen] = useState(false);
59	    const normalizedValue = normalizeColorValue(value, accentColor, swatches);
60	    const allowPickerChanges = useRef(false);
61	    const suppressPickerChanges = useRef(false);
62	    const selectedSwatch = swatches.find((swatch) => {
63	        return swatch.value === value || (value && swatch.hex.toLowerCase() === value.toLowerCase());
64	    });
65	
66	    return (
67	        <Popover
68	            open={open}
69	            onOpenChange={(nextOpen) => {
70	                allowPickerChanges.current = false;
71	                suppressPickerChanges.current = false;
72	                setOpen(nextOpen);
73	            }}
74	        >
75	            <PopoverTrigger asChild>
76	                <div className="flex w-full cursor-pointer items-start justify-between">
77	                    <span className="mt-px flex-1">{title}</span>
78	                    <div className="flex shrink-0 gap-1">
79	                        {open && swatches.length > 0 && (
80	                            <div className="flex items-center gap-1">
81	                                {swatches.map((swatch) => {
82	                                    const swatchValue = swatch.value === undefined ? swatch.hex : swatch.value;
83	                                    const isSelected = selectedSwatch?.title === swatch.title;
84	
85	                                    return (
86	                                        <button
87	                                            key={swatch.title}
88	                                            aria-label={swatch.title}
89	                                            className={`relative flex h-5 w-5 shrink-0 cursor-pointer items-center overflow-hidden rounded-full border border-grey-300 dark:border-grey-800 ${isSelected ? 'outline-2 outline-green' : ''}`}
90	                                            style={{backgroundColor: swatch.hex}}
91	                                            title={swatch.title}
92	                                            type="button"
93	                                            onClick={() => {
94	                                                allowPickerChanges.current = false;
95	                                                suppressPickerChanges.current = true;
96	                                                onChange(swatchValue);
97	                                                setOpen(false);
98	                                            }}
99	                                        >
100	                                            {isTransparent(swatch.hex) && <TransparentIndicator />}
101	                                        </button>
102	                                    );
103	                                })}
104	                            </div>
105	                        )}
106	                        <button
107	                            aria-label="Pick color"
108	                            className="relative size-6 cursor-pointer rounded-full border border-grey-250 dark:border-grey-800"
109	                            type="button"
110	                        >
111	                            <div className="absolute inset-0 rounded-full bg-[conic-gradient(hsl(360,100%,50%),hsl(315,100%,50%),hsl(270,100%,50%),hsl(225,100%,50%),hsl(180,100%,50%),hsl(135,100%,50%),hsl(90,100%,50%),hsl(45,100%,50%),hsl(0,100%,50%))]" />
112	                            <div className="absolute inset-[3px] overflow-hidden rounded-full border border-white dark:border-grey-950" style={{backgroundColor: normalizedValue}} />
113	                        </button>
114	                    </div>
115	                </div>
116	            </PopoverTrigger>
117	            <PopoverContent
118	                align="end"
119	                className="w-auto p-4"
120	                onEscapeKeyDown={(event) => {
121	                    event.stopPropagation();
122	                }}
123	            >
124	                <div
125	                    onInputCapture={() => {
126	                        allowPickerChanges.current = true;
127	                    }}
128	                    onKeyDownCapture={() => {
129	                        allowPickerChanges.current = true;
130	                    }}
131	                    onMouseDownCapture={() => {
132	                        allowPickerChanges.current = true;
133	                    }}
134	                    onPointerDownCapture={() => {
135	                        allowPickerChanges.current = true;
136	                    }}
137	                    onTouchStartCapture={() => {
138	                        allowPickerChanges.current = true;
139	                    }}
140	                >
141	                    <ColorPicker
142	                        value={normalizedValue}
143	                        onChange={(hex: string) => {
144	                            if (suppressPickerChanges.current || !allowPickerChanges.current) {
145	                                return;
146	                            }
147	
148	                            onChange(hex);
149	                        }}
150	                    />
151	                </div>
152	            </PopoverContent>
153	        </Popover>
154	    );
155	};
156	
157	export default ColorPickerField;
