describe('tmp escape', function () {
    it('keeps modal open when Escape pressed with picker open (mounted)', async function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });

        await act(async () => {
            fireEvent.click(screen.getByText('Button color'));
            await Promise.resolve();
            await new Promise(resolve => setTimeout(resolve, 0));
